# Control C6 - executable concurrency SCHEDULE controls for the bounded read-only recovery
# protocol.
#
# Not fixed coherent tuples. The reader is a coroutine that yields after EVERY observation, and a
# concurrent writer's steps are released between those yields. Every monotone assignment of writer
# steps to reader-yield slots is enumerated, so temporally skewed observations genuinely occur
# (including root's schedule 1, where the witness advances across the journal snapshot, and root's
# schedule 2, where the writer commits and exits after the reader's ledger snapshot).
#
# usage: python c6-schedules.py <reportPath>
import itertools
import json
import sys

OUT = sys.argv[1]
PKD = 'e' * 64
EXEC = 'exec1_' + '1' * 32


def bsha(seq):
    """Stand-in for the domain-framed body digest of the row at seq."""
    return '%064x' % seq


# --------------------------------------------------------------------------- world
class World:
    def __init__(self, tail0, floor0, commitSeq, corrupt=None):
        self.tail = tail0
        self.witness = {'witnessSchema': 1, 'projectKeyDigest': PKD, 'grantGeneration': 1,
                        'seq': tail0, 'state': 'COMMITTED', 'bodySha256': bsha(tail0)}
        self.floor = {'projectKeyDigest': PKD, 'grantGeneration': 1,
                      'lastSeq': floor0, 'tailSha256': bsha(floor0) if floor0 else None}
        self.receipts = {}
        self.attempts = {EXEC: 'admitted'}
        self.commitSeq = commitSeq
        self.everCommitted = False
        self.ledgerVersion = 0
        if corrupt == 'committedBeyondTail':
            # a genuinely adverse, STABLE carrier state that no writer step will change
            self.witness = dict(self.witness, seq=tail0 + 3, bodySha256=bsha(tail0 + 3))
        if corrupt == 'tailBelowFloor':
            self.floor = {'projectKeyDigest': PKD, 'grantGeneration': 1,
                          'lastSeq': tail0 + 5, 'tailSha256': bsha(tail0 + 5)}

    # lawful writer steps
    def w_witness_pending(self):
        self.witness = dict(self.witness, seq=self.commitSeq, state='PENDING',
                            bodySha256=bsha(self.commitSeq))

    def w_append_durable(self):
        self.tail = self.commitSeq

    def w_witness_committed(self):
        self.witness = dict(self.witness, seq=self.commitSeq, state='COMMITTED',
                            bodySha256=bsha(self.commitSeq))

    def w_ledger_commit(self):
        self.ledgerVersion += 1
        self.receipts[EXEC] = self.commitSeq
        self.everCommitted = True

    def w_floor_copy(self):
        self.floor = {'projectKeyDigest': PKD, 'grantGeneration': 1,
                      'lastSeq': self.tail, 'tailSha256': bsha(self.tail)}

    def w_attempt_settle(self):
        self.ledgerVersion += 1
        self.attempts[EXEC] = 'settled'

    # reader-visible observations
    def snap_ledger(self):
        return {'version': self.ledgerVersion, 'receipts': dict(self.receipts),
                'attempts': dict(self.attempts)}

    def snap_journal(self):
        return {'tail': self.tail, 'tailSha256': bsha(self.tail) if self.tail else None}

    def read_witness(self):
        return dict(self.witness)

    def read_floor(self):
        return dict(self.floor)


COMMITTING = ['w_witness_pending', 'w_append_durable', 'w_witness_committed',
              'w_ledger_commit', 'w_floor_copy', 'w_attempt_settle']
# a refused attempt: the SEAL becomes durable, no evidence commit is ever issued (F36 orphan)
REFUSED = ['w_witness_pending', 'w_append_durable', 'w_witness_committed',
           'w_floor_copy', 'w_attempt_settle']
# an attempt refused before any append
EARLY_REFUSED = ['w_attempt_settle']


# --------------------------------------------------------------------------- reader
def witness_shape_ok(w):
    keys = {'witnessSchema', 'projectKeyDigest', 'grantGeneration', 'seq', 'state', 'bodySha256'}
    if not isinstance(w, dict) or set(w.keys()) != keys:
        return False
    if w['witnessSchema'] != 1 or type(w['seq']) is bool or not isinstance(w['seq'], int):
        return False
    if w['state'] not in ('PENDING', 'COMMITTED'):
        return False
    if w['state'] == 'PENDING' and w['seq'] < 1:
        return False
    return True


def classify(cap, k):
    """(anchorClass, adverseCondition, adverseIsCorruptionClaim) for one capture."""
    J, W, H = cap['J'], cap['W'], cap['H']
    t = J['tail']
    if not witness_shape_ok(W):
        return None, 'witnessMalformed', True
    if W['projectKeyDigest'] != PKD or W['grantGeneration'] != 1:
        return None, 'witnessForeignCarrier', True
    if H['lastSeq'] > t:
        return None, 'tailBelowObservedFloor', True
    floorOk = (H['lastSeq'] == 0) or (H['tailSha256'] == bsha(H['lastSeq']))
    if not floorOk:
        return None, 'floorContradictsTail', True
    if W['state'] == 'COMMITTED' and W['seq'] == t and W['bodySha256'] == bsha(t):
        return 'witness-committed-tail', None, False
    if W['state'] == 'PENDING' and W['seq'] == t and W['bodySha256'] == bsha(t):
        return 'witness-pending-at-tail', None, False
    if W['state'] == 'PENDING' and W['seq'] == t + 1:
        if k is not None and k <= H['lastSeq']:
            return 'sc-trust-floor', None, False
        return None, 'aboveFloorUnderPendingNextSlot', False
    return None, 'witnessStateUnreconciled', True


def usable(anchorClass, cap):
    if anchorClass in ('witness-committed-tail', 'witness-pending-at-tail'):
        return cap['stableW']
    if anchorClass == 'sc-trust-floor':
        return cap['stableH'] and cap['stableW'] is not None
    return False


def reader(world, counters):
    """Coroutine. Yields a label after every observation; returns the conclusion.

    Read-only and bounded: exactly one ledger snapshot, at most two journal snapshots, at most
    four witness reads, at most four floor reads. No lock, no wait on the writer, no mutation, no
    witness repair, no high-water raise, no new grant, and no in-memory active-set consultation.
    """
    def obs(kind, value):
        counters[kind] += 1
        return value

    # Step 1: ONE coherent ledger snapshot carrying receipt, association and the ledger-owned
    # attempt phase together.
    L = obs('ledger', world.snap_ledger())
    yield 'ledger-snapshot'

    k = L['receipts'].get(EXEC)
    phase = L['attempts'].get(EXEC)

    if k is None:
        # Step 2: absence path, decided entirely inside that one snapshot.
        if phase is None:
            return 'unknown-attempt-unobserved'
        if phase == 'admitted':
            return 'unknown-attempt-open'
        return 'terminal-not-committed'

    # Steps 3-6: bracketed capture. Stability of a bracket is what makes an observation usable.
    caps = []
    for attempt in (1, 2):
        w1 = obs('witness', world.read_witness())
        yield 'witness-before'
        h1 = obs('floor', world.read_floor())
        yield 'floor-before'
        J = obs('journal', world.snap_journal())
        yield 'journal-snapshot'
        w2 = obs('witness', world.read_witness())
        yield 'witness-after'
        h2 = obs('floor', world.read_floor())
        yield 'floor-after'
        cap = {'J': J, 'W': w2, 'H': h2, 'stableW': w1 == w2, 'stableH': h1 == h2}
        caps.append(cap)
        a, adverse, isCorruptionClaim = classify(cap, k)
        hazard = k > J['tail']
        if a is not None and usable(a, cap) and not hazard:
            return 'committed-historically:' + a
        if attempt == 1:
            continue

        # second and final capture: decide conservatively
        stableTail = (caps[0]['J']['tail'] == caps[1]['J']['tail']
                      and caps[0]['J']['tailSha256'] == caps[1]['J']['tailSha256'])
        if hazard:
            if cap['stableH'] and cap['H']['lastSeq'] >= k and stableTail:
                return 'unknown-quarantine-condition'
            return 'unavailable-busy'
        if adverse == 'aboveFloorUnderPendingNextSlot':
            return 'unknown-custody'
        if adverse is not None:
            # An owner quarantine/corruption condition is reportable ONLY from stable
            # observations: both brackets byte-identical AND two journal snapshots agreeing
            # on the tail seq and tail digest.
            if isCorruptionClaim and not (cap['stableW'] and cap['stableH'] and stableTail):
                return 'unavailable-busy'
            return 'unknown-quarantine-condition'
        return 'unavailable-busy'


def run(make_world, writer_steps, slots):
    """Release writer step i into reader-yield slot slots[i] (non-decreasing)."""
    world = make_world()
    counters = {'ledger': 0, 'journal': 0, 'witness': 0, 'floor': 0}
    gen = reader(world, counters)
    wi = 0
    n = len(writer_steps)
    yielded = 0
    while wi < n and slots[wi] == 0:
        getattr(world, writer_steps[wi])()
        wi += 1
    conclusion = None
    ledgerSnap = None
    while True:
        try:
            label = next(gen)
        except StopIteration as e:
            conclusion = e.value
            break
        if label == 'ledger-snapshot':
            ledgerSnap = world.snap_ledger()
        yielded += 1
        while wi < n and slots[wi] == yielded:
            getattr(world, writer_steps[wi])()
            wi += 1
    while wi < n:
        getattr(world, writer_steps[wi])()
        wi += 1
    return world, counters, conclusion, ledgerSnap


MAX_SLOT = 11   # reader yields at most 11 times (1 ledger + 2 captures x 5 observations)

CONFIGS = [
    ('A committing attempt, receipt at tail+0', lambda: World(9, 9, 10), COMMITTING, False),
    ('B root schedule 1 shape: receipt below tail, writer appends above it',
     lambda: World(10, 9, 11), COMMITTING, False),
    ('C committing attempt with a lagging floor', lambda: World(10, 5, 11), COMMITTING, False),
    ('D refused attempt leaving an orphan SEAL (F36)', lambda: World(9, 9, 10), REFUSED, False),
    ('E attempt refused before any append', lambda: World(9, 9, 10), EARLY_REFUSED, False),
    ('F genuinely corrupt: witness COMMITTED beyond the tail, stable',
     lambda: World(9, 9, 10, corrupt='committedBeyondTail'), COMMITTING, True),
    ('G genuinely corrupt: tail below the observed floor, stable',
     lambda: World(9, 9, 10, corrupt='tailBelowFloor'), COMMITTING, True),
]

results = []
violations = []
for label, mk, steps, isCorrupt in CONFIGS:
    n = len(steps)
    for slots in itertools.combinations_with_replacement(range(MAX_SLOT + 1), n):
        world, counters, conclusion, ledgerSnap = run(mk, steps, slots)
        receiptInSnapshot = ledgerSnap is not None and EXEC in ledgerSnap['receipts']
        row = {'config': label, 'slots': list(slots), 'conclusion': conclusion,
               'everCommitted': world.everCommitted,
               'receiptInSnapshot': receiptInSnapshot, 'counters': dict(counters)}
        bad = []
        if not isCorrupt and conclusion == 'unknown-quarantine-condition':
            bad.append('false-quarantine-from-lawful-writer')
        if conclusion == 'terminal-not-committed' and world.everCommitted:
            bad.append('false-terminal-not-committed')
        if conclusion.startswith('committed') and not receiptInSnapshot:
            bad.append('committed-without-receipt-in-snapshot')
        if counters['ledger'] != 1:
            bad.append('ledger-snapshot-count')
        if counters['journal'] > 2:
            bad.append('journal-snapshot-bound')
        if counters['witness'] > 4 or counters['floor'] > 4:
            bad.append('observation-bound')
        if bad:
            row['violations'] = bad
            violations.append(row)
        results.append(row)

hist = {}
per_config = {}
for r_ in results:
    key = r_['conclusion'].split(':')[0]
    hist[key] = hist.get(key, 0) + 1
    per_config.setdefault(r_['config'], {})
    per_config[r_['config']][key] = per_config[r_['config']].get(key, 0) + 1

# the corrupt configs must actually be able to report the condition, else the stability gate
# would have silently disabled the diagnosis altogether
corrupt_reports = {c: per_config[c].get('unknown-quarantine-condition', 0)
                   for c, _, _, isC in [(x[0], x[1], x[2], x[3]) for x in CONFIGS] if isC}

rep = {
    'control': 'c6-schedules',
    'model': ('reader coroutine yielding after every observation; writer steps released into '
              'reader-yield slots; every monotone slot assignment enumerated'),
    'maxReaderYields': MAX_SLOT,
    'configs': [c[0] for c in CONFIGS],
    'totalSchedules': len(results),
    'conclusionHistogram': hist,
    'perConfigHistogram': per_config,
    'corruptConfigsStillReportTheCondition': corrupt_reports,
    'violations': violations[:20],
    'violationCount': len(violations),
    'allInvariantsHeld': not violations,
    'invariants': [
        'I1 no quarantine/corruption conclusion from a lawful writer, in any schedule',
        'I2 no terminal not-committed conclusion for an attempt that committed at any point',
        'I3 no committed conclusion unless the receipt was in the single ledger snapshot',
        'I4 read-only and bounded: exactly 1 ledger snapshot, at most 2 journal snapshots, '
        'at most 4 witness and 4 floor reads, 0 mutations',
        'I5 a genuinely corrupt carrier is still diagnosable, so the stability gate does not '
        'silently disable the diagnosis',
    ],
}
with open(OUT, 'w', encoding='utf-8') as fh:
    fh.write(json.dumps(rep, indent=1) + '\n')
print('WROTE', OUT)
print('schedules', len(results), 'violations', len(violations))
print('histogram', json.dumps(hist, sort_keys=True))
print('corrupt configs still diagnosable', json.dumps(corrupt_reports))
for c in CONFIGS:
    print(' ', c[0][:58], json.dumps(per_config[c[0]], sort_keys=True))
for v in violations[:8]:
    print('  VIOLATION', v['violations'], v['config'], v['slots'])

